    var dark = 0; for (r = 0; r < size; r++) for (c = 0; c < size; c++) if (m[r][c]) dark++;
    var pct = dark * 100 / (size * size);
    var k = Math.floor(Math.abs(pct - 50) / 5); score += k * 10;
