    var bytes = toBytes(text);
    var version = forceVersion || chooseVersion(level, bytes.length);
    var size = 17 + version * 4;
    var dataCw = encodeData(bytes, level, version);
    var allCw = buildCodewords(dataCw, level, version);

    var base = createMatrix(size);
    placeFinder(base, 0, 0);
    placeFinder(base, 0, size - 7);
    placeFinder(base, size - 7, 0);
    placeAlignment(base, version);
    placeTimingAndStatics(base, version);
    reserveFormat(base);
    reserveVersion(base, version);
    placeData(base, allCw);

